-- funciones (definición exacta del lab) y su ACL
CREATE OR REPLACE FUNCTION public.is_admin(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = 'admin'
  )
$function$
;
revoke all on function public.is_admin(uuid) from public;
grant execute on function public.is_admin(uuid) to public;
grant execute on function public.is_admin(uuid) to anon;
grant execute on function public.is_admin(uuid) to authenticated;
grant execute on function public.is_admin(uuid) to service_role;
CREATE OR REPLACE FUNCTION public.is_super_admin(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.super_admins
    WHERE user_id = _user_id
  )
$function$
;
revoke all on function public.is_super_admin(uuid) from public;
grant execute on function public.is_super_admin(uuid) to public;
grant execute on function public.is_super_admin(uuid) to anon;
grant execute on function public.is_super_admin(uuid) to authenticated;
grant execute on function public.is_super_admin(uuid) to service_role;
CREATE OR REPLACE FUNCTION public.has_section_permission(_user_id uuid, _section text, _permission text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 
    CASE WHEN public.is_super_admin(_user_id) THEN true
    ELSE EXISTS (
      SELECT 1 FROM public.user_permissions
      WHERE user_id = _user_id 
        AND section_key = _section
        AND (
          (_permission = 'view' AND can_view = true) OR
          (_permission = 'edit' AND can_edit = true)
        )
    )
    END
$function$
;
revoke all on function public.has_section_permission(uuid,text,text) from public;
grant execute on function public.has_section_permission(uuid,text,text) to service_role;
CREATE OR REPLACE FUNCTION public.can_read_section(_section text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.has_section_permission((select auth.uid()), _section, 'view')
$function$
;
revoke all on function public.can_read_section(text) from public;
grant execute on function public.can_read_section(text) to authenticated;
grant execute on function public.can_read_section(text) to service_role;
CREATE OR REPLACE FUNCTION public.can_write_section(_section text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- 'view' A PROPOSITO. Ver el bloque de comentario de arriba.
  -- Para exigir can_edit: cambiar 'view' por 'edit' aqui, y nada mas.
  select public.has_section_permission((select auth.uid()), _section, 'view')
$function$
;
revoke all on function public.can_write_section(text) from public;
grant execute on function public.can_write_section(text) to authenticated;
grant execute on function public.can_write_section(text) to service_role;
CREATE OR REPLACE FUNCTION public.can_edit_section(_section text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.has_section_permission((select auth.uid()), _section, 'edit')
$function$
;
revoke all on function public.can_edit_section(text) from public;
grant execute on function public.can_edit_section(text) to authenticated;
grant execute on function public.can_edit_section(text) to service_role;
CREATE OR REPLACE FUNCTION private.sesion_panel_permitida()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1 FROM auth.users u WHERE u.id = auth.uid()
      AND (u.banned_until IS NULL OR u.banned_until <= now())
      AND EXISTS (SELECT 1 FROM auth.sessions s WHERE s.user_id = u.id
        AND s.id::text = auth.jwt()->>'session_id')
  )
$function$
;
revoke all on function private.sesion_panel_permitida() from public;
grant execute on function private.sesion_panel_permitida() to authenticated;
CREATE OR REPLACE FUNCTION public.ejecutar_limpieza_gdpr()
 RETURNS TABLE(tabla text, accion text, registros_procesados integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config RECORD;
  v_count integer;
  v_fecha_limite date;
BEGIN
  FOR v_config IN SELECT * FROM gdpr_config WHERE activo = true
  LOOP
    v_count := 0;
    v_fecha_limite := CURRENT_DATE - v_config.dias_retencion;
    
    -- Procesar según la tabla y acción
    IF v_config.tabla = 'reservas' AND v_config.accion = 'anonimizar' THEN
      UPDATE reservas SET
        nombre = 'Cliente Anonimizado',
        email = NULL,
        telefono = NULL,
        notas_cliente = NULL
      WHERE fecha < v_fecha_limite
        AND nombre IS DISTINCT FROM 'Cliente Anonimizado';
      GET DIAGNOSTICS v_count = ROW_COUNT;
      
    ELSIF v_config.tabla = 'resenas' AND v_config.accion = 'anonimizar' THEN
      UPDATE resenas SET
        nombre_cliente = 'Cliente Anonimizado',
        email = NULL
      WHERE fecha < v_fecha_limite
        AND nombre_cliente IS DISTINCT FROM 'Cliente Anonimizado';
      GET DIAGNOSTICS v_count = ROW_COUNT;
      
    ELSIF v_config.tabla = 'blacklist' AND v_config.accion = 'eliminar' THEN
      DELETE FROM blacklist 
      WHERE created_at < v_fecha_limite::timestamptz;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    END IF;
    
    -- Registrar en auditoría si hubo cambios
    IF v_count > 0 THEN
      INSERT INTO gdpr_audit_log (accion, tabla, registros_afectados, detalles)
      VALUES (
        v_config.accion,
        v_config.tabla,
        v_count,
        jsonb_build_object(
          'dias_retencion', v_config.dias_retencion,
          'fecha_limite', v_fecha_limite,
          'campos_afectados', v_config.campos_anonimizar
        )
      );
    END IF;
    
    tabla := v_config.tabla;
    accion := v_config.accion;
    registros_procesados := v_count;
    RETURN NEXT;
  END LOOP;
END;
$function$
;
revoke all on function public.ejecutar_limpieza_gdpr() from public;
grant execute on function public.ejecutar_limpieza_gdpr() to authenticated;
grant execute on function public.ejecutar_limpieza_gdpr() to service_role;
CREATE OR REPLACE FUNCTION public.append_tool_call_log(p_call_id text, p_new_tools jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Si no existe el call_log aún (la llamada acaba de empezar), lo creamos mínimo
  INSERT INTO call_logs (vapi_call_id, restaurant_id, call_type, status, started_at, tool_calls)
  VALUES (p_call_id, 'default', 'bot', 'active', now(), p_new_tools)
  ON CONFLICT (vapi_call_id) DO UPDATE
  SET tool_calls = COALESCE(call_logs.tool_calls, '[]'::jsonb) || p_new_tools;
END;
$function$
;
revoke all on function public.append_tool_call_log(text,jsonb) from public;
grant execute on function public.append_tool_call_log(text,jsonb) to authenticated;
grant execute on function public.append_tool_call_log(text,jsonb) to service_role;
CREATE OR REPLACE FUNCTION public.cleanup_old_security_logs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM public.security_log
  WHERE created_at < NOW() - INTERVAL '90 days';
  
  DELETE FROM public.rate_limit_log
  WHERE created_at < NOW() - INTERVAL '7 days';
END;
$function$
;
revoke all on function public.cleanup_old_security_logs() from public;
grant execute on function public.cleanup_old_security_logs() to authenticated;
grant execute on function public.cleanup_old_security_logs() to service_role;
CREATE OR REPLACE FUNCTION public.recalcular_ocupacion_historica(fecha_desde date DEFAULT NULL::date, fecha_hasta date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer := 0;
  v_fecha_inicio date;
  v_fecha_fin date;
BEGIN
  v_fecha_inicio := COALESCE(fecha_desde, CURRENT_DATE - interval '1 year');
  v_fecha_fin := COALESCE(fecha_hasta, CURRENT_DATE);
  
  -- Limpiar datos existentes en el rango
  DELETE FROM ocupacion_diaria 
  WHERE fecha BETWEEN v_fecha_inicio AND v_fecha_fin;
  
  -- Insertar datos agregados desde reservas
  INSERT INTO ocupacion_diaria (
    fecha, hora, espacio_id, sala_id,
    total_comensales, total_reservas,
    reservas_confirmadas, reservas_canceladas, reservas_no_show,
    comensales_confirmados, dia_semana, turno
  )
  SELECT 
    r.fecha,
    r.hora,
    r.sala_id,
    r.sala_id,
    SUM(r.numero_comensales),
    COUNT(*),
    COUNT(*) FILTER (WHERE r.estado = 'confirmada'),
    COUNT(*) FILTER (WHERE r.estado = 'cancelada'),
    COUNT(*) FILTER (WHERE r.estado = 'no_show'),
    COALESCE(SUM(r.numero_comensales) FILTER (WHERE r.estado = 'confirmada'), 0),
    EXTRACT(DOW FROM r.fecha)::integer,
    CASE WHEN r.hora < '16:00' THEN 'comida' ELSE 'cena' END
  FROM reservas r
  WHERE r.fecha BETWEEN v_fecha_inicio AND v_fecha_fin
  GROUP BY r.fecha, r.hora, r.sala_id
  ON CONFLICT (fecha, hora, sala_id) DO UPDATE SET
    total_comensales = EXCLUDED.total_comensales,
    total_reservas = EXCLUDED.total_reservas,
    reservas_confirmadas = EXCLUDED.reservas_confirmadas,
    reservas_canceladas = EXCLUDED.reservas_canceladas,
    reservas_no_show = EXCLUDED.reservas_no_show,
    comensales_confirmados = EXCLUDED.comensales_confirmados,
    dia_semana = EXCLUDED.dia_semana,
    turno = EXCLUDED.turno,
    updated_at = now();
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;
revoke all on function public.recalcular_ocupacion_historica(date,date) from public;
grant execute on function public.recalcular_ocupacion_historica(date,date) to authenticated;
grant execute on function public.recalcular_ocupacion_historica(date,date) to service_role;

-- políticas (pg_policies del lab, incluida la restrictiva acceso_panel_no_bloqueado)
create policy "Admins can manage gdpr_config" on public.gdpr_config as permissive for all to public using (is_admin(auth.uid()));
create policy "Auth can manage gdpr_config" on public.gdpr_config as permissive for all to authenticated using (true) with check (true);
create policy "acceso_panel_no_bloqueado" on public.gdpr_config as restrictive for all to authenticated using (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida)) with check (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida));
create policy "Admins can view gdpr_audit_log" on public.gdpr_audit_log as permissive for select to public using (is_admin(auth.uid()));
create policy "Auth can manage gdpr_audit_log" on public.gdpr_audit_log as permissive for all to authenticated using (true) with check (true);
create policy "acceso_panel_no_bloqueado" on public.gdpr_audit_log as restrictive for all to authenticated using (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida)) with check (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida));
create policy "Authenticated users can delete security logs" on public.security_log as permissive for delete to authenticated using (true);
create policy "Authenticated users can insert security logs" on public.security_log as permissive for insert to authenticated with check (true);
create policy "Authenticated users can read security logs" on public.security_log as permissive for select to authenticated using (true);
create policy "Authenticated users can update security logs" on public.security_log as permissive for update to authenticated using (true) with check (true);
create policy "Service role can insert security logs" on public.security_log as permissive for insert to service_role with check (true);
create policy "acceso_panel_no_bloqueado" on public.security_log as restrictive for all to authenticated using (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida)) with check (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida));
create policy "Authenticated users can delete rate limits" on public.rate_limit_log as permissive for delete to authenticated using (true);
create policy "Authenticated users can insert rate limits" on public.rate_limit_log as permissive for insert to authenticated with check (true);
create policy "Authenticated users can read rate limits" on public.rate_limit_log as permissive for select to authenticated using (true);
create policy "Authenticated users can update rate limits" on public.rate_limit_log as permissive for update to authenticated using (true) with check (true);
create policy "Service role can manage rate limits" on public.rate_limit_log as permissive for all to service_role using (true) with check (true);
create policy "acceso_panel_no_bloqueado" on public.rate_limit_log as restrictive for all to authenticated using (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida)) with check (( SELECT private.sesion_panel_permitida() AS sesion_panel_permitida));
create policy "Auth can manage sell_users" on public.sell_users as permissive for all to authenticated using (true) with check (true);
create policy "Los usuarios pueden actualizar su propio perfil" on public.sell_users as permissive for update to public using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "Los usuarios pueden crear su propio perfil" on public.sell_users as permissive for insert to public with check ((auth.uid() = user_id));
